def compute(vars):
    debt = vars["v1"]
    equity = vars["v2"]

    if equity == 0:
        return None

    ratio = debt / equity

    return {
        "value": ratio,
        "trace": {
            "debt_securities": debt,
            "equity_securities": equity,
            "calculation": "debt_securities / equity_securities",
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
